function netatmoCallbackPage(returnTarget,{ok,title,detail=''}){const safeTarget=netatmoHtmlEscape(returnTarget),safeTitle=netatmoHtmlEscape(title),safeDetail=netatmoHtmlEscape(detail);return new Response(`<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark"><title>MID В· Netatmo</title><style>body{margin:0;font-family:system-ui,-apple-system,BlinkMacSystemFont,"SF Pro Text",sans-serif;background:#eef4f7;color:#12273a;min-height:100dvh;display:grid;place-items:center;padding:24px;box-sizing:border-box}.card{max-width:560px;width:100%;background:#fff;border:1px solid #d7e3eb;border-radius:24px;padding:24px;box-sizing:border-box;box-shadow:0 16px 48px #10233818}.status{font-size:13px;font-weight:800;color:${ok?'#168a61':'#b83d3d'};margin-bottom:10px}h1{font-size:24px;margin:0 0 10px}p{color:#617386;line-height:1.5;margin:0 0 18px}.button{display:block;text-align:center;text-decoration:none;background:#087eea;color:white;padding:14px 18px;border-radius:14px;font-weight:800}@media(prefers-color-scheme:dark){body{background:#07111f;color:#f4f8fc}.card{background:#0e2034;border-color:#29415a}p{color:#a8bacb}}</style></head><body><main class="card"><div class="status">${ok?'VERBUNDEN':'NICHT VERBUNDEN'}</div><h1>${safeTitle}</h1>${safeDetail?`<p>${safeDetail}</p>`:''}<a class="button" href="${safeTarget}">ZurГјck zu MID</a></main></body></html>`,{status:200,headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store, no-cache, must-revalidate','referrer-policy':'no-referrer','x-frame-options':'DENY'}})}
async function netatmoPrepareAuthorization(request,env,connectionIdValue,returnUrlValue){if(!netatmoConfigured(env))throw Object.assign(new Error('Netatmo ist im Worker noch nicht konfiguriert.'),{status:503});const connectionId=validStationConnectionId(connectionIdValue),returnUrl=stationReturnUrl(returnUrlValue,request,env);if(!connectionId||!returnUrl)throw Object.assign(new Error('UngГјltige Stationskennung oder RГјcksprungadresse.'),{status:400});const state=pushB64Encode(crypto.getRandomValues(new Uint8Array(32))),stateKey=`netatmo-state:${await pushHash(state)}`;await env.MID_PUSH_SUBSCRIPTIONS.put(stateKey,JSON.stringify({connectionId,returnUrl,createdAt:Date.now()}),{expirationTtl:900});const authorize=new URL('https://api.netatmo.com/oauth2/authorize');authorize.searchParams.set('client_id',String(env.NETATMO_CLIENT_ID));authorize.searchParams.set('redirect_uri',netatmoRedirectUri(request));authorize.searchParams.set('response_type','code');authorize.searchParams.set('scope','read_station');authorize.searchParams.set('state',state);return{authorizeUrl:authorize.toString(),redirectUri:netatmoRedirectUri(request)}}
