function validVentilationTime(value,fallback){const raw=String(value||'');return/^([01]\d|2[0-3]):[0-5]\d$/.test(raw)?raw:fallback}
function validVentilationRoomRules(value){return(Array.isArray(value)?value:[]).map(row=>({roomId:String(row?.roomId||'').slice(0,120),enabled:row?.enabled!==false,earliest:validVentilationTime(row?.earliest,'00:00'),latest:validVentilationTime(row?.latest,'23:59'),minMinutes:clamp(Math.round(Number(row?.minMinutes)||15),10,45),maxMinutes:clamp(Math.round(Number(row?.maxMinutes)||30),15,60)})).filter(row=>row.roomId&&row.enabled)}
function validVentilationPushConfig(value){if(!value?.enabled)return null;const connectionId=validStationConnectionId(value?.connectionId),roomRules=validVentilationRoomRules(value?.roomRules);return connectionId&&roomRules.length?{enabled:true,connectionId,deviceId:String(value?.deviceId||'').slice(0,120),roomRules}:null}
function ventilationClockMinutes(value){const match=String(value||'').match(/(\d{2}):(\d{2})/);return match?Number(match[1])*60+Number(match[2]):0}
function ventilationAllowedAt(time,earliest,latest){const now=ventilationClockMinutes(String(time).slice(11,16)),start=ventilationClockMinutes(earliest),end=ventilationClockMinutes(latest);return start<=end?now>=start&&now<=end:now>=start||now<=end}
