function ventilationWeatherSafe(row){const code=number(row.weatherCode),pop=number(row.precipitationProbability),precip=number(row.precipitation),gust=number(row.gustKmh);if([code,pop,precip,gust].some(value=>value===undefined))return false;return![95,96,99].includes(code)&&pop<=55&&precip<.4&&gust<=45}
